WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET DEFINE OFF
SET SQLBLANKLINES ON
DECLARE
  n NUMBER;
BEGIN
  SELECT (SELECT COUNT(*) FROM T_CORE_I18N_CONFIG) + (SELECT COUNT(*) FROM T_CORE_I18N) + (SELECT COUNT(*) FROM T_CORE_I18N_MESSAGE) + (SELECT COUNT(*) FROM T_CORE_TABLE) + (SELECT COUNT(*) FROM T_CORE_TABLE_HIERARCHY) + (SELECT COUNT(*) FROM T_CORE_MENU) + (SELECT COUNT(*) FROM T_CORE_SYSTEM_CONFIG) + (SELECT COUNT(*) FROM T_CORE_LOGIN_CONFIG) + (SELECT COUNT(*) FROM T_CORE_ADMIN_SELECT_CONFIG) INTO n FROM DUAL;
  IF n <> 0 THEN RAISE_APPLICATION_ERROR(-20120, 'Bootstrap target configuration must be empty.'); END IF;
END;
/
COMMIT;
